// app/(dashboard)/orders/page.tsx — серверный компонент + стриминг
import { Suspense } from 'react';
import { auth } from '@/lib/auth';
import { OrdersList } from './orders-list';        // клиентский лист (фильтры, клики)
import { OrdersStats } from './orders-stats';       // серверный компонент

export default async function OrdersPage({ searchParams }: {
  searchParams: Promise<{ status?: string }>;
}) {
  const { status } = await searchParams;
  const session = await auth();                    // см. 9.2.4
  if (!session) redirect('/login');

  return (
    <section>
      <Suspense fallback={<StatsSkeleton />}>
        <OrdersStats tenantId={session.tenantId} />  {/* медленный запрос не блокирует страницу */}
      </Suspense>
      <OrdersList initialStatus={status} />          {/* 'use client' внутри */}
    </section>
  );
}

