// 3) Server Action: валидация + авторизация на сервере
'use server';
const CreateOrderSchema = z.object({ sku: z.string(), qty: z.number().int().positive() });

export async function createOrder(prev: FormState, formData: FormData) {
  const session = await auth();
  if (!session) return { error: 'unauthorized' };            // доверяем только серверу

  const parsed = CreateOrderSchema.safeParse({
    sku: formData.get('sku'), qty: Number(formData.get('qty')),
  });
  if (!parsed.success) return { error: parsed.error.issues[0].message };

  try {
    const order = await api.post('/orders', parsed.data, { token: session.accessToken });
    revalidateTag('orders');
    return { ok: true, id: order.id };
  } catch (e) {
    reportError(e);                                        // Sentry/лог с correlation id
    return { error: 'create failed, try later' };          // не течём внутренними деталями
  }
}

// middleware.ts — гейт до рендеринга (проверка структуры, не бизнес-логики)
export { default } from 'next-auth/middleware'; // или своя реализация ниже

export function middleware(req: NextRequest) {
  const { pathname } = req.nextUrl;
  const hasSession = Boolean(req.cookies.get('access_token')?.value);
  const isPublic = pathname === '/login' || pathname.startsWith('/public');

  if (!hasSession && !isPublic) {
    const url = new URL('/login', req.url);
    url.searchParams.set('from', pathname);
    return NextResponse.redirect(url);
  }
  if (hasSession && pathname === '/login') return NextResponse.redirect(new URL('/dashboard', req.url));
  return NextResponse.next();
}
export const config = { matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'] };

// lib/api-server.ts — серверный клиент API (используется только в RSC/actions)
import 'server-only';                       // ошибка сборки, если попало в клиентский бандл

export async function api<T>(path: string, init: RequestInit & { token?: string } = {}): Promise<T> {
  const res = await fetch(`${process.env.INTERNAL_API_URL}${path}`, {
    ...init,
    headers: { 'content-type': 'application/json', ...(init.token && { authorization: `Bearer ${init.token}` }), ...init.headers },
    cache: 'no-store',
    signal: AbortSignal.timeout(5_000),
  });
  if (!res.ok) throw new ApiError(res.status, await res.text());
  return res.json() as Promise<T>;
}
